{
  "findings": [
    {
      "title": "Schedule of Events table header has inconsistent cycle numbering",
      "page": 61,
      "quote": "Cycle 12, 3 / Cycle 2 to 42, 3 / Cycles 5+2, 3",
      "severity": "major"
    },
    {
      "title": "Footnote 2 contradicts cycle durations in table header",
      "page": 62,
      "quote": "Cycle 1 is 7 weeks long, cycles 2 through 4 are 6 weeks long, and all subsequent cycles are 9 weeks long.",
      "severity": "major"
    },
    {
      "title": "Footnote 3 references C1D50 but cycle 1 is 7 weeks (49 days)",
      "page": 62,
      "quote": "C1D50 may be the same visit as C2D1",
      "severity": "major"
    },
    {
      "title": "Footnote 6 says ICF must be obtained within 45 days prior to C1D1, but Section 9.2.1 says re-consent if prior ICF signing is beyond 45 days",
      "page": 62,
      "quote": "must be obtained within 45 days prior to cycle1 day 1",
      "severity": "minor"
    },
    {
      "title": "Footnote 6 says all screening assessments within 28 days, but Section 9.2.1 says some procedures may not need repeat if within 28 days",
      "page": 62,
      "quote": "All screening assessments must be performed within 28 days prior to cycle 1 day 1",
      "severity": "minor"
    },
    {
      "title": "Footnote 18 says PK samples every other cycle for first 2 years, but Table 2 shows PK at every cycle day 1",
      "page": 63,
      "quote": "collected from all patients pre-dose (Ctrough) on cycle 1 day 1 and every other cycle for the first 2 years of treatment",
      "severity": "major"
    },
    {
      "title": "Footnote 19 says ADA samples at cycles 3 and 5, but Table 2 shows ADA at every cycle day 1",
      "page": 63,
      "quote": "pre-dose of cemiplimab on day 1 of cycles 3 and 5 for the first year of treatment",
      "severity": "major"
    },
    {
      "title": "Section 9.1.2 says EOT visit 30 days after last dose, but Table 2 shows EOT at 30 days ±7 days",
      "page": 63,
      "quote": "All patients will attend an end of treatment visit 30 days after their last dose of study drug.",
      "severity": "minor"
    },
    {
      "title": "Section 9.1.2 says primary endpoint visit is cycle 4 day 43, but footnote 2 says cycles 2-4 are 6 weeks (42 days)",
      "page": 63,
      "quote": "before the primary endpoint visit (cycle 4 day 43)",
      "severity": "major"
    },
    {
      "title": "Section 9.2.3.6 says TSH with reflex T3, free T4, but later says if TSH abnormal, T3 and free T4 should be measured",
      "page": 66,
      "quote": "TSH (with reflex T3, free T4)",
      "severity": "minor"
    },
    {
      "title": "Section 9.2.3.6 says pregnancy test ≤72 hours prior to study drug administration, but Table 2 shows pregnancy test at screening day -28 to -1",
      "page": 67,
      "quote": "Serum β-HCG or urine β-HCG will be measured ≤72 hours prior to study drug administration",
      "severity": "minor"
    },
    {
      "title": "Section 9.2.10 says pharmacogenomics sample may be collected during screening or any other time point, but Table 2 shows only at screening",
      "page": 69,
      "quote": "This sample may be collected during screening or any other time point for study-related research (Table 2)",
      "severity": "minor"
    }
  ]
}
